	}
	if err := admin.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname=$1)`, siblingSchema).Scan(&exists); err != nil {
		t.Fatal(err)
	}
	if !exists {
