name: CI

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

jobs:
  test:
    runs-on: ubuntu-latest
    timeout-minutes: 20
    steps:
      - name: Check out source
        uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6

      - name: Set up Go
        uses: actions/setup-go@b7ad1dad31e06c5925ef5d2fc7ad053ef454303e # v7
        with:
          go-version-file: go.mod
          cache-dependency-path: go.sum

      - name: Set up Node
        uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6
        with:
          node-version: '22'
          cache: npm
          cache-dependency-path: |
            sdk/gamehub-js/package-lock.json
            web/package-lock.json

      - name: Install locked dependencies
        run: make deps

      - name: Audit locked Node dependencies
        # What ships is held to the strict line: any advisory, any severity.
        shell: bash
        run: |
          set -Eeuo pipefail
          npm --prefix sdk/gamehub-js audit --omit=dev --audit-level=low
          npm --prefix web audit --omit=dev --audit-level=low

      - name: Report advisories on the test toolchain
        # Test-only packages ship to nobody, and a fresh advisory against one of
        # them used to turn the branch red on a day the tree never changed - a
        # gate no commit can pass is a gate that only teaches people to ignore
        # it. Record what is outstanding here and raise it on its own change.
        if: always()
        shell: bash
        run: |
          {
            echo '## Advisories on dev dependencies'
            echo
            echo '```'
            npm --prefix sdk/gamehub-js audit --audit-level=low 2>&1 || true
            npm --prefix web audit --audit-level=low 2>&1 || true
            echo '```'
          } >> "$GITHUB_STEP_SUMMARY"

      - name: Verify release contract
        run: make check-contract

      - name: Lint
        run: make lint

      - name: Test
        run: make test

      - name: Test Go concurrency under the race detector
        run: make test-race

      - name: Scan reachable Go vulnerabilities
        shell: bash
        run: |
          set -Eeuo pipefail
          go install golang.org/x/vuln/cmd/govulncheck@v1.6.0
          "$(go env GOPATH)/bin/govulncheck" ./...

      - name: Build application
        run: make build

      - name: Build container
        run: make docker-build

      - name: Resolve image name
        id: image
        shell: bash
        run: echo "name=igame:v$(tr -d '[:space:]' < VERSION)" >> "${GITHUB_OUTPUT}"

      - name: Scan final runtime image
        uses: anchore/scan-action@e1165082ffb1fe366ebaf02d8526e7c4989ea9d2 # v7.4.0
        with:
          image: ${{ steps.image.outputs.name }}
          fail-build: true
          severity-cutoff: high
          grype-version: v0.117.0
          output-format: table

      - name: Verify offline game-platform image contents
        shell: bash
        run: |
          set -Eeuo pipefail
          image="igame:v$(cat VERSION)"
          test "$(docker image inspect --format '{{.Architecture}}' "${image}")" = "amd64"
          test "$(docker image inspect --format '{{.Config.User}}' "${image}")" = "10001:10001"
          test "$(docker image inspect --format '{{ index .Config.Labels "io.igame.build.go-version" }}' "${image}")" = "1.26.6"
          container_id="$(docker create "${image}")"
          binary_dir="$(mktemp -d)"
          cleanup() {
            docker rm --force "${container_id}" >/dev/null 2>&1 || true
            rm -rf -- "${binary_dir}"
          }
          trap cleanup EXIT
          docker cp "${container_id}:/app/igame" "${binary_dir}/igame"
          mkdir -p "${binary_dir}/licenses"
          docker cp "${container_id}:/licenses/." "${binary_dir}/licenses"
          go version -m "${binary_dir}/igame" | grep -Fq 'go1.26.6'
          test -x "${binary_dir}/igame"
          test -r "${binary_dir}/licenses/web/package.json"
          test -r "${binary_dir}/licenses/web/package-lock.json"
          test -r "${binary_dir}/licenses/sdk/gamehub-js/package.json"
          test -r "${binary_dir}/licenses/sdk/gamehub-js/package-lock.json"
